import test from 'node:test';import assert from 'node:assert/strict';import {Game} from '../src/engine.js';import {RoomFeatures} from '../src/room-features.js';import {updateBoss} from '../src/boss-choreography.js';import {ActionAnimation} from '../src/action-animation.js';
const game=(room=9)=>{const g=new Game({seed:32});g.room=room;g.setupRoom();g.start();return g;};
test('packing visible parcels conserves dirt and opening is accounted only once',()=>{const g=game();const total=()=>g.dirt.reduce((n,v)=>n+v,0)+g.stage.pendingDirt;const before=total(),p=g.stage.parcels[0];const cargo=p.cargo,cleaned=g.stats.cleaned;g.stage.open(p);assert.ok(total()<=before-cargo+1e-4);const after=g.stats.cleaned;assert.ok(after>=cleaned+cargo);g.stage.open(p);assert.equal(g.stats.cleaned,after);assert.equal(g.stats.parcels,1);});
test('creating parcels moves existing dirt without changing cleanliness',()=>{const g=game(1),before=g.cleanExact;g.room=9;g.stage=new RoomFeatures(g);assert.ok(Math.abs(g.cleanExact-before)<.0001);});
test('combat victory still clears unopened parcels and a clean victory can end a boss act',()=>{const g=game(12);for(const e of g.enemies)e.alive=false;g.update(1/60);assert.equal(g.clearReason,'combat');assert.equal(g.stage.pendingDirt,0);const h=game(12);h.dirt.fill(0);h.stage.finish();h.update(1/60);assert.equal(h.clearReason,'clean');assert.equal(h.hazards.length,0);});
test('wind carries bubbles; belt moves player; pause freezes both',()=>{const g=game(5);g.gadgets.makeBubble(400,g.height*.48,0);let b=g.gadgets.bubbles[0],x=b.x;g.stage.update(.1);assert.ok(b.x>x);const h=game(9);h.player.y=h.height*.7;x=h.player.x;h.stage.update(.1);assert.ok(h.player.x>x);h.togglePause();x=h.player.x;const time=h.stage.time;h.update(.1);assert.equal(h.player.x,x);assert.equal(h.stage.time,time);});
test('late boss locks its telegraph, travels, rests and never becomes invulnerable',()=>{const g=game(12),boss=g.enemies.find(e=>e.type==='boss');updateBoss(g,boss,.01);const angle=boss.chargeAngle;g.player.x=42;updateBoss(g,boss,.1);assert.equal(boss.chargeAngle,angle);boss.actTime=0;updateBoss(g,boss,.01);assert.equal(boss.act,'roll');const x=boss.x,y=boss.y;updateBoss(g,boss,.1);assert.ok(Math.hypot(boss.x-x,boss.y-y)>10);boss.actTime=0;updateBoss(g,boss,.01);assert.equal(boss.act,'rest');updateBoss(g,boss,.01);assert.equal(boss.vulnerable,true);g.hitEnemy(boss,10000);assert.equal(boss.alive,false);});
test('action keyframes freeze on pause and recover without changing game simulation',()=>{const a=new ActionAnimation();a.fire(100);assert.equal(a.pose,'brace');a.update(.08,{active:true});assert.equal(a.pose,'recoil');a.update(2,{active:false});assert.equal(a.pose,'recoil');a.update(.3,{active:true,gathering:10});assert.equal(a.pose,'suction');a.update(1,{active:true,gathering:0});assert.equal(a.pose,'idle');a.reset();assert.equal(a.pose,'idle');});
test('fan telegraphs a fixed gust and a captured fan cannot keep blowing',()=>{const g=game(7),e=g.enemies.find(e=>e.type==='fan');e.guarded=false;e.x=g.player.x-130;e.y=g.player.y;e.attack=0;g.update(1/60,{angle:0});assert.ok(e.windup>0);const a=e.gustAngle;g.player.y+=100;g.update(1/60,{angle:0});assert.equal(e.gustAngle,a);g.gadgets.makeBubble(e.x,e.y,0);g.update(1/60,{angle:0});assert.equal(e.trapped,true);assert.equal(e.windup,0);assert.equal(e.gust,0);});
test('all packaged action frames share an identical planted-foot baseline',async()=>{const {CHARACTER_FRAMES,framePlacement}=await import('../src/character-frames.js');for(const key of Object.keys(CHARACTER_FRAMES)){const p=framePlacement(key);assert.equal(p.y+p.height,0);assert.equal(p.height,74);assert.ok(p.width>40&&p.width<80);}});
